      "body": "당신은 눈앞의 일뿐만 아니라 그 너머까지도 꿰뚫어볼 수 있는 사람이에요. 지금 이 한 수가 반년 후, 1년 후에 어떻게 효과를 발휘할지——긴 시간 축에서 생각할 수 있어요. 그래서 주변이 당장의 이익과 손해로 일희일비할 때에도, 당신은 '그것보다 최종적으로 어떻게 될지'를 보고 있어요. 모두가 오늘의 승패로 떠들고 있는 옆에서, 당신만이 세 수 앞의 판을 응시하고 있을 거예요. 그 큰 그림을 보는 관점이 당신의 판단에 흔들림 없는 무게를 부여하고 있어요.\n\n그리고 단순히 내다보는 것뿐만 아니라 실제로 이끌 수 있어요. 방침을 정하면 주변을 끌어들여 움직이게 하는 행동력이 있어요. ‘생각만 하는 사람’으로 끝나지 않고, 사람들을 이끌어 구상을 현실로 만들어요. 당신이 선두에 서서 '이렇게 진행한다'고 보여주면, 흩어져 있던 집단이 하나의 방향을 향하기 시작해요. 당신이 있기만 해도, 제각각이던 사람들이 하나의 조직이 된다——그런 장면을 당신은 여러 번 만들어 왔을 거예요.\n\n게다가 당신은 힘만으로 움직이지 않아요. 계획성이 높아 장기적인 그림을 현실적인 진행으로 옮길 수 있어요. ‘이 목표에 대해 언제, 누가, 무엇을’을 냉정하게 구성할 수 있어요. 그래서 당신의 계획에는 현실성이 있어요. 이상만을 말하는 장군이 아니라, 이기기 위한 길까지 그릴 수 있는 장군이기 때문에 주변 사람들이 안심하고 그 지휘에 따를 수 있어요.\n\n더욱이 당신은 남에게 아첨하지 않고 신뢰를 얻을 수 있는 사람이에요. 사랑받기 위해 판단을 굽히지 않아요. 옳다고 생각한 것을, 설령 일시적으로 반대받아도 관철할 수 있는 중심이 있어요. 상황이 혼란스러워도 동요하지 않고 담담하게 다음 수를 둘 수 있는 담력도 있어요. 전망·행동력·일의 진행·담력——그 모든 것이 갖추어져 있기 때문에, 당신은 안심하고 전체를 맡길 수 있는 장수가 될 수 있어요. 사람은 흔들리지 않는 사람의 등 뒤를 꼭 따라가는 거예요."
