      "title": "잘 맞는 사람",
      "body": "당신과 잘 맞는 사람은 깊이 파고드는 당신을 귀찮아하기보다 흥미롭게 바라보는 사람이에요. 날카로운 지적도 감정적으로 반응하지 않고 받아들여요. 혼자만의 시간을 존중하면서 마음속에 쌓인 감정에도 조용히 다가와 주는 상대 곁에서 당신의 탐구심은 자유롭게 뻗어 나가요.\n\n친구든 연인이든 중요한 건 침묵도 편안하게 받아들이는 관계예요. 억지로 대화를 이어 가지 않고 각자 다른 일을 해도 안심할 수 있는 사람과 깊이 연결될 수 있어요. 당신은 넓고 얕은 교류보다 소수의 사람과 진심을 나누는 관계를 원해요. 섬세함과 쉽게 타협하지 않는 마음을 함께 존중하는 상대와는 말이 적어도 단단한 신뢰가 자라요."
