      "heading": "마이페이스 상어 — “다들 그렇게 하니까”라는 이유로는 납득하지 못해요",
      "body": "당신은 '모두가 그렇게 하고 있으니까'라는 이유를 내세우지 않는 분이에요. 세상의 당연한 것을 당연하게 여기지 않아요. ‘이거, 정말 필요한가?’ ‘더 잘할 수 있지 않을까?’라고, 아무도 의심하지 않았던 전제를 의심할 수 있어요. 그런 관점이 있기 때문에, 당신은 기존의 방식을 깨고 새로운 길을 만들어 낼 수 있어요. 세계를 한 걸음 나아가게 하는 사람은 언제나 당신과 같은 '다시 묻는 사람'이에요.\n\n그리고 당신에게는 흔들리지 않는 비전이 있어요. ‘이래야 한다’는 미래상이 뚜렷하게 보이고 있어요. 그래서 주변에서 뭐라고 해도 흔들리지 않아요. 반대받고 웃음거리가 되어도, '아니, 이것이 옳다'고 믿는 길을 나아가요. 그 확신의 강함이 사람을 끌어당겨요. 처음에는 아무도 이해하지 못해도, 당신이 형태로 보여줄 때 모두가 '그런 뜻이구나'라고 깨닫게 돼요.\n\n당신은 세세한 것보다 큰 그림을 그리는 것을 잘해요. 규칙이나 절차에 얽매이기보다 “결국 어떤 모습이면 가장 좋을까?”라는 질문으로 큰 방향을 그릴 수 있어요. 보통의 단계를 하나씩 밟기보다, 곧바로 본질을 짚어 낼 수 있어요. 그 대담함이 있기 때문에, 아무도 생각하지 못했던 것을 만들어낼 수 있어요. 당신에게 있어서 제약은 지키는 것이 아니라, 극복하는 거예요.\n\n더욱이 당신은 비판에 동요하지 않아요. 새로운 일을 하면 반드시 반발이 오지만, 당신은 매번 상처받지 않아요. 오히려 '모르겠다면, 알게 해 주겠다'며 더 의욕적으로 나서요. 타협하여 원만하게 해결하는 것보다 자신의 미학을 관철하는 것을 선택할 수 있어요. 의심하고, 믿고, 뛰어넘고, 관철하는——그 모든 것을 할 수 있기 때문에, 당신은 세상을 진심으로 바꿀 수 있는 몇 안 되는 사람이에요."
