      "body": "당신이 조심하고 싶은 것은 자신의 비전이 강한 만큼 주변을 뒤처지게 하는 거예요. 당신에게는 보이는 미래가 모두에게는 아직 보이지 않아요. ‘왜 모르는 거야?’라며 이해가 늦은 상대에게 짜증이 나요. 옳음으로 밀어붙인 결과, 사람이 따라오지 못해 고립되어 있던—그런 일이 있지 않나요?\n\n그리고 타협을 허용하지 않는 만큼, 주변에 같은 기준을 요구하여 엄격해지기 쉬워요. ‘이대로는 안 된다, 다시 시작하자’가 입버릇이 되어 상대를 위축시키고 있어요. 당신이 정한 기준이 너무 높아서, 주변 사람들은 몇 번이나 결과물을 다시 내도 합격점을 받기 어려워요. 문득 보니 모두가 당신의 표정을 살피고 있어요——마음에 떠오르는 일이 없나요?\n\n큰 그림을 그리는 것은 잘하지만, 세밀한 마무리나 꾸준한 운용은 서투른 경우도 있어요. 구상은 최고인데 실행 준비가 따라가지 못해 주변이 뒷수습에 나서고 있어요. 아이디어를 흩뿌리고, 회수는 누군가에게 전적으로 맡기는——그런 장면, 있지 않나요?\n\n하지만 이것은 모두 '세상을 진심으로 더 좋게 만들고 싶다'는 타협 없는 이상의 표현이에요. 그 열정은 당신에게만 있는 무기예요. 비전을 혼자서 제시하는 것이 아니라, 믿어주는 동료와 나눌 수 있을 때, 당신의 혁명은 혼자만의 생각이 아니라 진정으로 세상을 움직이는 힘이 돼요."
