      "body": "당신의 뿌리에 있는 것은 마음속에 펼쳐지는 부드럽고 풍부한 상상의 세계예요. 겉으로는 조용해 보여도, 당신의 내면은 언제나 다채로워요. ‘이랬으면 좋겠다’며 이야기를 넓히거나, 좋아하는 것들의 세계에 조용히 잠기기도 해요. 그 풍부한 내면이 당신만의 매력을 만들어내고 있어요. 조용해 보이지만 가장 넓은 세상을 살아가는 것은 당신일지도 몰라요.\n\n멍하니 있는 것처럼 보여도 머릿속에서는 이것저것 상상하고 있던 적은 없나요? 영화나 이야기 속 사소한 장면을 보고 자신도 놀랄 만큼 눈물을 흘린 적은 없나요? 당신은 다른 사람들이 지나치기 쉬운 작은 것에서도 아름다움과 의미를 발견하는 사람이에요.\n\n그리고 당신은 사람에게 친절해요. 이상을 소중히 여기는 만큼, 사람의 아픔에도 민감하며, 친구가 우울해하면 자신의 일처럼 마음 아파하며 진심으로 상담에 응하게 돼요. 그 깊은 공감에 주변 사람들은 '이 사람이라면 이야기할 수 있겠다'고 느껴요. 당신 주변에는 언제나 따뜻한 분위기가 흐르고 있어요.\n\n사실 당신은 남몰래 꾸준히 노력하는 사람이기도 해요. 연습하고 조사하며 실력을 쌓지만, 그 과정을 사람들에게 드러내는 건 조금 쑥스러워요. 충분히 익숙해진 뒤에야 아무렇지 않은 듯 결과를 보여 주곤 해요. 최선을 다했는데도 실패할까 봐 두려워서 “별로 열심히 한 건 아니야”라고 말한 적은 없나요? 힘들이지 않고 잘하는 듯한 모습 뒤에는 아무도 모르는 노력이 쌓여 있어요.\n\n더욱이 당신은 자신의 '좋아함'과 '이렇게 있고 싶다'에 솔직해요. 세상의 잣대보다 자신의 마음이 움직이는 것을 믿을 수 있어요. 그 순수함이 있기 때문에, 당신의 내면에는 언젠가 말이나 형태로 만들고 싶은 세계가 조용히 자라고 있어요. 상상하고, 공감하고, 다가가고, 조용히 노력하고, 믿는——그 모든 것을 할 수 있기 때문에, 당신이 그리는 다정함은 주변의 현실까지 조금씩 부드럽게 만들어 가요."
