      "body": "조심할 점은 독특한 감성이 주변에 전달되기 어렵다는 거예요. 남과 다른 시각을 가지고 있기 때문에 '무슨 생각을 하는지 알 수 없다'고 생각되곤 하지 않나요? 당신 안에서는 제대로 논리가 통하는데, 밖에서는 수수께끼처럼 보여요.\n\n예를 들어, 모두가 좋다고 하는 것이 당신에게는 별로 와 닿지 않아 혼자 다른 반응을 보이다가 조금 어색해진 적은 없나요? 기분의 기복 때문에 주변 사람들이 '지금 기분이 어떨까?' 하고 당신의 기분을 가늠하기 어려워할 때도 있지 않나요? 당신은 까다로운 것이 아니라 자신의 감각에 솔직한 것뿐이에요.\n\n그리고 아무도 주목하지 않는 것에 혼자 열중하다가 그 재미를 이해받지 못해 몰래 외로워질 때도 있어요. 사실은 공유하고 싶은 마음도 있는데, '어차피 전달되지 않을 거야'라며 처음부터 포기하고 혼자서 감당하고 있지 않나요? 섬세한 만큼, 전달되지 않는 부분이 은근히 답답하게 느껴져요.\n\n하지만 이것은 모두 당신이 자신의 감성을 소중히 여기고 있다는 증거예요. 남에게 맞추지 않고 끝까지 지키는 것은 훌륭한 강함이에요. 당신의 독특한 시선에 위로를 받거나 재미를 느끼는 분들이 분명히 있어요. 억지로 모두에게 맞출 필요는 없어요. 다만, 가끔 '나는 이렇게 느낀다'고 말로 표현해 보면, 당신의 세계에 끌리는 사람이 제대로 다가와요."
