    {
      "title": "사용설명서",
      "heading": "살뜰한 강아지 — 모임에서 누구보다 먼저 사람들을 챙겨요. — 진행자가 아니어도 모두의 잔을 챙겨요",
      "body": "사람들의 작은 변화를 누구보다 빨리 알아차리는 편이에요. ‘오늘은 조금 기운이 없어 보이네’, ‘웃고 있지만 어딘가 힘들어 보여’처럼 모두가 지나치기 쉬운 신호도 자연스럽게 포착해요. 모임에서 가장 먼저 ‘괜찮아?’ 하고 말을 거는 사람도 대개 당신일 거예요. 변화를 눈치채는 데서 그치지 않고 실제로 손을 내밀 수 있다는 점이 큰 장점이에요.\n\n또 사람들과 어울리기를 좋아해, 어려움을 겪는 사람이 보이면 자연스럽게 다가가요. 회식이나 모임에서도 주최자가 아닌데 어느새 음료와 분위기를 챙기고 있지 않나요? ‘세심하다’는 말을 자주 듣는 이유예요. 누군가를 위해 움직이는 일이 숨 쉬듯 자연스러워요.\n\n이 배려는 말에 그치지 않아요. ‘괜찮아?’라고 묻는 데서 끝내지 않고, 필요한 일을 찾아 직접 도와줘요. 한번 챙긴 사람은 그 뒤에도 계속 살펴요. 그래서 주변 사람들은 당신을 진심으로 믿고 의지해요. 당신이 있는 모임에는 남다른 안정감이 있어요.\n\n무엇보다 멀리 있는 이상보다 지금 눈앞에 있는 사람의 행복을 중요하게 여겨요. 현실에 단단히 발을 딛은 다정함으로 한 사람 한 사람을 구체적으로 도울 수 있어요. 알아차리고, 움직이고, 끝까지 챙기는 당신은 주변에서 ‘이 사람이 있어서 다행이다’라는 말을 듣는 소중한 존재예요."
    },
    {
      "title": "조심해야 할 점",
      "heading": "남을 챙기느라 자신을 뒤로 미루지 않도록",
      "body": "남을 지나치게 챙기느라 자신을 뒤로 미루지 않도록 주의해야 해요. 누군가 곤란해하면 그냥 지나치지 못해 이리저리 돕다 보니, 어느새 자신이 뒷전으로 밀릴 수 있어요. 집에 돌아온 뒤에야 지쳐 있다는 사실을 깨달은 적은 없나요?\n\n도움을 요청받는 일이 기뻐 결국 모든 일을 맡아버리기도 해요. ‘내가 해야 해’라는 마음으로 혼자 짊어지다 보면 어느새 한계에 다다라요. 늘 누군가를 받쳐주는 역할에 익숙한 탓에, 정작 도움을 받는 데 서툴지는 않나요?\n\n사람의 감정에 민감한 만큼 상대의 기분과 주변 분위기까지 자기 몫처럼 짊어질 때도 있어요. 누군가 기분이 좋지 않으면 혹시 자신 때문은 아닌지 고민하며, 신경 쓰지 않아도 될 일까지 마음에 담아둬요.\n\n이 모든 모습은 눈앞의 사람을 행복하게 해 주고 싶은 깊은 다정함에서 나와요. 다만 그 친절을 가끔은 자신에게도 돌려주세요. 늘 다른 사람을 지지해 온 당신 역시 충분히 돌봄을 받을 자격이 있어요."
    },
    {
      "title": "잘 맞는 사람",
      "body": "당신과 잘 맞는 사람은 당신의 배려를 당연하게 여기지 않고 고마움을 돌려주는 사람이에요. 챙김을 받기만 하지 않고 가끔은 당신도 기대게 해 줘요. “내가 도움이 될까?”라는 불안에 “네가 있어 기뻐”라고 답해 주는 상대 곁에서 당신은 안심하고 다정함을 나눌 수 있어요.\n\n친구든 연인이든 중요한 건 주저하지 않고 기댈 수 있는 관계예요. 걱정이 많은 당신을 귀찮아하지 않고 무리할 때는 쉬어도 괜찮다고 말해 주는 사람과 오래 따뜻하게 함께할 수 있어요. 당신이 챙기기만 하는 관계보다 서로 챙겨 주는 관계가 잘 맞아요. 함께 힘이 되어 주는 상대 곁에서 당신의 다정함도 더 풍성해져요."
    }
