      "body": "당신은 정한 목표를 향해 꾸준히 달려 나갈 수 있는 사람이에요. 사교적이고 행동력이 있으며, 지고 싶지 않은 마음도 강해요. 한번 하겠다고 결심하면 남들보다 몇 배는 더 노력할 수 있어요. 그 열정과 끈기가 당신의 가장 큰 강점이에요. 주변 사람들이 멈춰 서도 묵묵히 한 걸음씩 나아가며, 쌓아 온 노력이 어느새 쉽게 따라잡을 수 없는 차이를 만들어요.\n\n하겠다고 결심한 일은 잠자는 시간까지 아껴 가며 끝내려 하지 않나요? 주변에서 이제 충분하다고 말해도 스스로 정한 기준에 닿기 전까지는 만족하지 못해 무리할 때가 있어요. 당신의 진지함은 주변 사람들이 생각하는 것보다 훨씬 깊어요. 그래서 적당히 힘을 빼고 하는 일이 오히려 어려울 수 있어요.\n\n당신은 이상을 이야기하는 데서 그치지 않아요. 현실적이고 구체적으로 움직여 성과를 낼 수 있어요. “이렇게 되면 좋겠다”는 바람을 “이렇게 실현해 보자”는 방법으로 바꿀 수 있어요. 현실에 발을 딛고 꾸준히 노력하며 일을 앞으로 나아가게 해요. 당신이 있으면 팀은 목표에 한 걸음 더 가까워져요.\n\n또 자신이 믿는 길을 끝까지 지킬 수 있어요. 주변에 맞추려고 기준을 낮추거나, 여기까지 해내겠다는 마음을 쉽게 바꾸지 않아요. 그 단단한 중심 덕분에 노력이 중간에 그치지 않아요. 결정하고, 끝까지 달리고, 결과를 만들고, 믿는 바를 지켜 내는 힘이 있어요. 그래서 당신이 쌓아 온 노력은 분명한 실력으로 이어져요."
