      "heading": "너무 애쓰다 쉬는 법을 잊지 않도록",
      "body": "당신이 조심해야 할 것은 무리해서 자신을 몰아붙이는 거예요. 목표에 몰두하는 만큼, 할 수 없는 자신을 용서할 수 없게 돼요. 주변에서 '이제 충분하지 않아?'라고 말해도, 자신의 기준에 도달할 때까지 만족하지 못해 멈출 수 없었던 적이 있지 않나요? 당신의 합격 점수는 언제나 당신 자신에게 가장 엄격하게 설정되어 있어요.\n\n그리고 목표를 달성해도 기뻐할 틈 없이 다음 과제가 신경 쓰일 때도 있어요. 한 산을 넘으면 바로 다음 산을 올려다보며 마음이 편안하지 않아요. 성취감을 느끼기 전에 달려 나가서 언제 만족할 수 있을까, 라고 느낀 적 없나요?\n\n하지 못했을 때, 필요 이상으로 자신을 탓하게 되는 경우도 있어요. 사실은 충분히 하고 있는데도 '아직 부족하다'며 자신을 몰아붙여요. 그 엄격함이 당신 자신을 소모시키고 있지 않나요?\n\n하지만 이것은 모두 '결정한 일을 진심으로 해내고 싶다'는 곧은 마음의 표현이에요. 멈춰 서서 여기까지 달려온 자신을 '잘했다'고 인정해 주세요. 쉬는 것은 게으름이 아니라 다음을 향한 충전이에요. 당신의 노력은 이미 제대로 결실을 맺고 있어요."
