      "body": "당신의 뿌리에는 '더 높은 곳에 가고 싶다'는 조용하지만 강한 성장 의지가 있어요. 누군가와 경쟁하는 것이 아니에요. 다만, 당신 안에 '이상적인 나'가 있어서, 그곳에 조금이라도 가까워지고 싶어 남몰래 노력을 계속하고 있어요. 그 모습을 일부러 사람들에게 보여주지는 않아요. 조용히 자신의 발로 한 걸음씩 고도를 올려 나가는 거예요.\n\n예를 들어, 목표를 세워도 달성할 수 있을 것 같으면 '아니, 아직 멀었어'라며 더 높은 기준으로 다시 쓰고 있지 않나요? 사람들 앞에서는 '전혀 못하고 있다'고 말하지만, 집에서는 누구보다도 엄격하게 노력하고 있어요. 당신이 '못하고 있다'고 말하는 것은 겸손해서가 아니라, 스스로도 정말 그렇게 생각하기 때문이에요.\n\n그리고 당신은 무리지어 다니지 않아요. 혼자서 묵묵히 나아가는 것이 당신의 성향에 맞아요. 하지만 그것은 외로움을 좋아하는 것이 아니라, 자신의 페이스가 흐트러지는 것을 원하지 않기 때문이에요. 이상을 향한 길은 자신의 발로 걷고 싶어요. 누군가에 맞추기보다는 자신의 납득을 우선할 수 있어요. 그 자립적인 강함이 당신을 확실히 높은 곳으로 이끌어 가요.\n\n더욱이 당신은 성실해요. ‘하겠다’고 결심한 일을, 지켜보는 사람이 없어도 끝까지 해낼 수 있어요. 대충 하지 않아요. 그 쌓아 온 노력이 어느새 진정한 실력이 되고 있어요. 의지를 가지고, 묵묵히, 자신의 발로, 끝까지 해내는 것——그 모든 것을 할 수 있기 때문에, 당신의 노력은 본인이 깨닫지 못하는 사이에 누군가의 동경이 되고 있어요."
