      "body": "당신의 뿌리에 있는 것은 '몇 번 쓰러져도 다시 일어선다'는 불굴의 강인함이에요. 높은 이상을 가지고 혼자서 묵묵히 나아가요. 하지만 당신은 실패해도 너무 낙심하지 않아요. ‘안 됐구나, 그럼 다음으로’라며 담담하게 전환하고 다시 걸음을 내딛을 수 있어요. 그 회복력이 당신의 가장 큰 무기예요. 쓰러지지 않는 사람보다 몇 번이고 일어나는 사람이 사실은 더 강해요.\n\n예를 들어, 큰 실수를 해도 하룻밤 자고 나면 의외로 태연해지지 않았나요? 주변 사람들이 '괜찮아?'라며 걱정하는데, 본인은 '벌써 다음 일을 생각하고 있다'는 상태로, 오히려 상대방을 당황하게 하는 일이 있지 않나요? 당신에게 실패는 끝이 아니라 통과점이에요.\n\n그리고 당신은 감정의 기복이 적어요. 그래서 장기적인 목표를 추구하거나 어려운 상황을 견디는 데 강해요. 단거리의 화려함은 없지만, 장거리에서 본래의 실력을 발휘해요. 모두가 마음이 무너져 탈락해 가는 가운데, 마지막까지 남아 있는 사람은 당신뿐일지도 몰라요. 그 끈기는 성실하게 쌓아 온 사람만이 낼 수 있는 거예요.\n\n더욱이 당신은 결과에 일희일비하지 않아요. 잘 되든 잘 안 되든 담담하게 자신이 해야 할 일을 계속할 수 있어요. 그 조용한 안정이 주변의 지주가 돼요. 일어나고, 전환하고, 버티고, 계속하는——그 모든 것을 할 수 있기 때문에, 당신의 불굴의 강함은 본인이 생각하는 것 이상으로 많은 사람들에게 용기를 주고 있어요."
