      "body": "조심할 점은 늘 강해 보여서 주변 사람들이 당신의 힘듦을 알아차리지 못할 수 있다는 거예요. 무슨 일이 있어도 다시 일어서는 모습을 보며, 주변에서는 “저 사람은 괜찮아”라고 생각하지 않나요? 다시 일어설 수 있다는 것과 상처받지 않는다는 것은 다른데 말이에요.\n\n사실은 힘들어도 표정에 잘 드러나지 않아 아무도 “괜찮아?”라고 묻지 않을 때가 있지 않나요? 실패에도 담담하게 대처하다 보니 “정신력이 강하네”라는 말로 넘어가고, 속으로 얼마나 힘든지는 알아주지 않을 수 있어요. 회복할 수 있다고 해서 아프지 않은 것은 아니에요.\n\n다른 사람에게 의지하는 게 어려워 “혼자 어떻게든 해 볼 수 있어”라며 모든 것을 떠안기도 해요. 혼자 다시 일어서는 데 익숙한 만큼 누군가에게 기대어 본 경험이 적을 수 있어요. 가끔은 다른 사람에게 기대어도 괜찮지 않을까요?\n\n이런 모습은 모두 자신의 힘으로 서고 싶은 조용한 자부심에서 나와요. 강한 사람도 힘들다고 말해도 괜찮아요. 당신이 조금 힘든 마음을 털어놓아도 주변 사람들은 떠나지 않아요. 오히려 늘 흔들림 없던 당신의 인간적인 모습에 안심할 수 있어요. 다시 일어서기 전에 충분히 쉬어도 괜찮아요."
