      "body": "당신은 그 자리의 분위기에서 즐거움을 만들어낼 수 있는 사람이에요. 가만히 있기보다는 움직이고 싶고, 재미있어 보이는 일에는 전력으로 뛰어들어요. 생각이 떠오르면 바로 행동할 수 있는 그 기세와 발빠른 움직임이 당신의 매력이에요. 평범한 일상을 당신은 순식간에 '이벤트'로 바꿔 버려요. ‘지루하다’라는 말이 당신 주변에는 가장 어울리지 않아요.\n\n예를 들어, '지금부터 놀러 가자!' 같은 갑작스러운 초대에 가장 신나게 응하는 사람은 당신이 아닌가요? 재미있어 보이는 것을 발견하면, 앞뒤를 생각하기보다 먼저 몸이 움직이고 있어요. 그 빠른 실행력 덕분에 주변 사람들도 자연스럽게 함께하게 되어, 어느새 모두가 즐거운 시간을 보내고 있는——그런 장면, 자주 있지 않나요?\n\n그리고 당신은 자신의 '즐거움'에 솔직해요. 주변에 맞추어 참는 것보다 자신이 진심으로 설렐 수 있는 것을 선택할 수 있어요. 그 솔직함이 있기 때문에, 당신의 즐거움에는 거짓이 없어요. 만들어진 것이 아닌 진짜 열정이 주변에도 전해져 가요. 당신과 함께 있으면 지루하지 않다고 말하는 것은 그 순도 때문이에요.\n\n더욱이 당신은 새로운 놀이 방법을 찾아내는 천재예요. 정해진 방식에 얽매이지 않고, '이렇게 하면 더 재미있지 않을까?'라는 아이디어를 계속해서 떠올릴 수 있어요. 행동하고, 사람들을 함께 이끌고, 솔직하게 즐기며, 새로운 것을 만들어 내는——그 모든 것이 가능하기 때문에, 당신이 있는 곳에는 언제나 웃음소리가 끊이지 않아요."
