      "body": "당신과 잘 맞는 사람은 자유를 구속하지 않고 엉뚱한 모습도 웃으며 받아 주는 사람이에요. 신나게 함께하다가도 활기찬 모습 뒤에 문득 외로워진 당신을 알아채요. “좋아, 같이 하자”라며 함께하는 상대 곁에서 당신은 마음껏 빛날 수 있어요.\n\n친구든 연인이든 중요한 건 외로운 마음도 솔직하게 보여 줄 수 있는 관계예요. 신나는 시간을 함께 즐기면서 조용해진 당신 곁에도 있어 주는 사람과 깊이 연결될 수 있어요. 긴 잔소리보다 웃음으로 마음이 통하는 상대가 잘 맞아요. 떠들썩한 시간과 편안하게 자기 모습으로 돌아오는 시간을 함께 나눌 수 있는 사람을 선택해 보세요."
