      "body": "당신이 조심해야 할 것은, 남을 너무 우선시해서 자신이 뒤로 미루어지는 것. 누군가를 위해서라면 움직일 수 있는데, 자신에 관한 일이 되면 '나는 괜찮아'라며 물러서게 되는—그런 적 있지 않나요? 당신의 친절 목록에 당신 자신의 이름이 올라와 있지 않아요.\n\n예를 들어, 자신이 피곤해도 친구가 우울해 보이면 자신을 잊고 이야기를 듣고 있지 않나요? 거절하는 것을 잘 못해서, 손해 보는 역할이라도 '괜찮아'라며 받아들이고, 나중에 혼자서 한숨을 쉬고 있어요. 당신의 '괜찮아'는 사실 괜찮지 않은 경우도 많을 거예요.\n\n그리고 자신의 감정을 말하는 것이 서툴러서, 누구에게도 말하지 못하고 쌓아두는 경우도 있어요. 남의 이야기는 얼마든지 들을 수 있는데, 자신의 이야기가 되면 '이런 말을 해도 괜찮을까' 하고 망설이다가 삼켜 버려요. 어느새 마음이 가득 차 있지 않나요?\n\n이런 모습은 주변 사람들이 행복했으면 좋겠다는 순수한 바람에서 나와요. 다만 자신의 마음이 지쳐 있으면 다른 사람을 오래 받쳐 주기도 어려워요. 자신을 소중히 여기는 것은 욕심이 아니에요. 당신은 이미 충분히 누군가에게 힘이 되고 있어요. 이제는 그 다정함을 자신에게도 조금 나눠 주세요."
