      "body": "당신에게는 좋아하는 것을 조용히 깊이 사랑하는 한결같은 마음이 있어요. 이것저것 관심을 넓히기보다 “이거다” 싶은 것을 오래 음미하고 싶어 해요. 유행이나 다른 사람의 평가에 휘둘리지 않고, 스스로 진심으로 좋다고 느끼는 것을 꾸준히 사랑할 수 있어요. 그 한결같은 마음이 당신의 매력이에요.\n\n좋아하는 것에 대해서는 주변 사람들이 놀랄 만큼 잘 알거나 확고한 취향이 있지 않나요? 남이 권한 것보다 스스로 찾아서 마음에 든 것을 오래도록 소중히 간직하지 않나요? 당신에게 좋아한다는 건 잠깐 소비하고 마는 것이 아니라, 알아 갈수록 마음이 깊어지는 일이에요.\n\n당신은 주변의 변화에 쉽게 흔들리지 않아요. 다른 사람들이 새로운 것에 몰려들어도 자신의 세계를 조용히 지켜요. 다들 좋아한다는 이유만으로 따라가지 않아요. 그 한결같음 덕분에 당신이 좋아하는 것에는 진심이 느껴져요. 일시적인 관심이 아니라 진심으로 좋아한다는 걸 알아보는 사람은 알아요.\n\n그러면서도 다른 사람에게 다정해요. 자신만의 세계를 소중히 여기면서 다른 사람의 취향도 존중해요. 누군가 무언가에 푹 빠져 있는 모습을 따뜻하게 지켜볼 수 있어요. 깊이 알아 가고, 소중히 지키고, 흔들리지 않으며, 서로의 취향을 인정하는 사람이에요. 그래서 당신이 무언가를 사랑하는 모습은 주변 사람들에게도 “좋아하는 것을 소중히 해도 괜찮구나”라는 마음을 전해 줘요."
